enum TxType { deposit, withdraw }

class Transaction {
  const Transaction(this.type, this.amount);
  final TxType type;
  final double amount;

  @override
  String toString() => '${type.name}: ${amount.toStringAsFixed(2)}';
}

class Account {
  double _balance = 0;
  final List<Transaction> _history = [];

  double get balance => _balance;
  List<Transaction> get history => List.unmodifiable(_history);

  void deposit(double amount) {
    if (amount <= 0) throw ArgumentError('存款必须为正');
    _balance += amount;
    _history.add(Transaction(TxType.deposit, amount));
  }

  void withdraw(double amount) {
    if (amount > _balance) throw StateError('余额不足');
    _balance -= amount;
    _history.add(Transaction(TxType.withdraw, amount));
  }
}

void main() {
  final account = Account()
    ..deposit(100)
    ..deposit(50)
    ..withdraw(30);
  for (final tx in account.history) {
    print(tx);
  }
  print('余额 ${account.balance.toStringAsFixed(2)}');
}

