Map<K, List<T>> groupBy<T, K>(List<T> items, K Function(T) keyOf) {
  final result = <K, List<T>>{};
  for (final item in items) {
    result.putIfAbsent(keyOf(item), () => <T>[]).add(item);
  }
  return result;
}

List<T> distinct<T>(List<T> items) {
  final seen = <T>{};
  final result = <T>[];
  for (final item in items) {
    if (seen.add(item)) result.add(item);
  }
  return result;
}

void main() {
  final words = ['apple', 'banana', 'avocado', 'berry'];
  final grouped = groupBy(words, (w) => w[0]);
  print(grouped['a']);
  print(grouped['b']);
  print(distinct([1, 2, 2, 3, 1]));
}

