class Cache<K, V> {
  final _store = <K, V>{};
  int hits = 0;
  int misses = 0;

  void put(K key, V value) => _store[key] = value;

  V? get(K key) {
    if (_store.containsKey(key)) {
      hits++;
      return _store[key];
    }
    misses++;
    return null;
  }

  bool containsKey(K key) => _store.containsKey(key);
  int get size => _store.length;
}

void main() {
  final cache = Cache<String, int>();
  cache.put('a', 1);
  cache.put('b', 2);
  print(cache.get('a'));
  print(cache.get('z') ?? -1);
  print('命中 ${cache.hits} 未命中 ${cache.misses}');
  print(cache.size);
}

