sealed class Result<T> {
  const Result();
}

class Ok<T> extends Result<T> {
  const Ok(this.value);
  final T value;
}

class Err<T> extends Result<T> {
  const Err(this.message);
  final String message;
}

Result<int> parseAge(String s) {
  final value = int.tryParse(s);
  if (value == null) return const Err('不是数字');
  if (value < 0) return const Err('不能为负');
  return Ok(value);
}

void main() {
  for (final s in ['20', 'x']) {
    switch (parseAge(s)) {
      case Ok(:final value):
        print('成功：$value');
      case Err(:final message):
        print('失败：$message');
    }
  }
}

class ConfigResult {
  ConfigResult(this.values, this.errors);
  final Map<String, String> values;
  final List<String> errors;
}

ConfigResult parseConfig(String text) {
  final values = <String, String>{};
  final errors = <String>[];
  for (final line in text.split('\n')) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) continue;
    final index = trimmed.indexOf('=');
    if (index <= 0) {
      errors.add('非法行：$trimmed');
      continue;
    }
    final key = trimmed.substring(0, index).trim();
    final value = trimmed.substring(index + 1).trim();
    values[key] = value;
  }
  return ConfigResult(values, errors);
}

void main() {
  const text = 'host=localhost\nport=8080\n坏行\nname = app';
  final result = parseConfig(text);
  print('host = ${result.values['host']}');
  print('port = ${int.parse(result.values['port']!)}');
  print('name = ${result.values['name']}');
  print('错误数：${result.errors.length}');
  for (final error in result.errors) {
    print(error);
  }
}

