import 'dart:io';

int countFiles(Directory dir) {
  var count = 0;
  for (final entity in dir.listSync()) {
    if (entity is File) {
      count++;
    } else if (entity is Directory) {
      count += countFiles(entity);
    }
  }
  return count;
}

