void expectEquals(Object? actual, Object? expected, String label) {
  if (actual != expected) {
    throw StateError('$label 失败：期望 $expected，实际 $actual');
  }
  print('通过 $label');
}

void main() {
  var passed = 0;

  void check(void Function() body) {
    body();
    passed++;
  }

  check(() => expectEquals(1 + 1, 2, '加法'));
  check(() => expectEquals('ab'.length, 2, '字符串长度'));
  check(() => expectEquals([1, 2, 3].last, 3, '末尾元素'));
  print('通过数 $passed');
}

class TestCase {
  TestCase(this.name, this.body);
  final String name;
  final void Function() body;
}

void runGroup(String title, List<TestCase> cases) {
  print('分组：$title');
  var passed = 0;
  for (final c in cases) {
    c.body();
    passed++;
  }
  print('  $passed/${cases.length} 通过');
}

