int parseScore(String text) {
  final trimmed = text.trim();
  if (trimmed.isEmpty) throw const FormatException('空输入');
  return int.parse(trimmed);
}

void main() {
  print(parseScore(' 90 '));
  print(parseScore('-5'));
  try {
    parseScore('abc');
  } on FormatException {
    print('非法输入被拒绝');
  }
}

class ValidationError implements Exception {
  ValidationError(this.message);
  final String message;
  @override
  String toString() => 'ValidationError: $message';
}

void validateAge(int age) {
  if (age < 0) throw ValidationError('年龄不能为负');
}

void main() {
  try {
    validateAge(-1);
  } on ValidationError catch (error) {
    print(error);
  }
  validateAge(18);
  print('年龄合法');
}

class Config {
  const Config(this.host, this.port);
  final String host;
  final int port;

  Config copyWith({String? host, int? port}) {
    return Config(host ?? this.host, port ?? this.port);
  }
}

void main() {
  const base = Config('localhost', 8080);
  final updated = base.copyWith(port: 9090);
  print('原始 ${base.host}:${base.port}');
  print('更新 ${updated.host}:${updated.port}');
}

class Point {
  const Point(this.x, this.y);
  final int x;
  final int y;

  @override
  bool operator ==(Object other) =>
      other is Point && other.x == x && other.y == y;

  @override
  int get hashCode => Object.hash(x, y);

  @override
  String toString() => 'Point($x, $y)';
}

void main() {
  final set = <Point>{
    const Point(1, 2),
    const Point(1, 2),
    const Point(3, 4),
  };
  print('集合大小 ${set.length}');
  print(set.contains(const Point(1, 2)));
}

class UserRepository {
  final Map<int, String> _store = <int, String>{1: '小明', 2: '小红'};
  String? findName(int id) => _store[id];
}

class UserService {
  UserService(this.repository);
  final UserRepository repository;
  String greet(int id) {
    final name = repository.findName(id);
    return name == null ? '未知用户' : '你好，$name';
  }
}

void main() {
  final service = UserService(UserRepository());
  print(service.greet(1));
  print(service.greet(99));
}

class AppConfig {
  AppConfig(this.values);

  final Map<String, String> values;

  static const Map<String, String> defaults = <String, String>{
    'host': 'localhost',
    'port': '80',
  };

  String get host => values['host'] ?? defaults['host']!;
  String get port => values['port'] ?? defaults['port']!;
}

void main() {
  final withOverride = AppConfig(<String, String>{'port': '8080'});
  print('${withOverride.host}:${withOverride.port}');
  final empty = AppConfig(<String, String>{});
  print('${empty.host}:${empty.port}');
}

int countOperations(int n) {
  var operations = 0;
  var sum = 0;
  for (var i = 1; i <= n; i++) {
    sum += i;
    operations++;
  }
  return operations;
}

void main() {
  for (final n in <int>[10, 100, 1000]) {
    print('n=$n 操作次数 ${countOperations(n)}');
  }
}

class Args {
  Args(this.command, this.flags);
  final String command;
  final Map<String, String> flags;

  static Args parse(List<String> input) {
    if (input.isEmpty) {
      throw ArgumentError('缺少命令');
    }
    final command = input.first;
    final flags = <String, String>{};
    for (var i = 1; i < input.length; i++) {
      final token = input[i];
      if (token.startsWith('--') && i + 1 < input.length) {
        flags[token.substring(2)] = input[++i];
      }
    }
    return Args(command, flags);
  }
}

void main() {
  final args = Args.parse(<String>['build', '--target', 'ohos', '--mode', 'release']);
  print('命令 ${args.command}');
  print('target=${args.flags['target']}');
  print('mode=${args.flags['mode']}');
  print('参数个数 ${args.flags.length}');
}
